int singleNumber(int *nums, int numsSize) {
  int ones = 0, twos = 0;
  for (int i = 0; i < numsSize; i++) {
    ones = ones ^ nums[i] & ~twos;
    twos = twos ^ nums[i] & ~ones;
  }
  return ones;
}

class Solution {
public:
  int singleNumber(vector<int> &nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
      ones = ones ^ num & ~twos;
      twos = twos ^ num & ~ones;
    }
    return ones;
  }
};
